import { M_lib_commerce_market_marketItem as marketItem } from "../../../../server.tsx";
import { M_lib_i18n_isLocale as isLocale } from "../../../../shared.tsx";
import { notFound as notFound } from "next/navigation";
import { M_components_BuyButton_BuyButton as BuyButton } from "../../../../ui.tsx";
import { M_components_Price_Price as Price } from "../../../../ui.tsx";
import { M_lib_app_copy_appCopy as appCopy } from "../../../../shared.tsx";
export const dynamic = "force-dynamic";
export default async function Page({ params }: {
    params: Promise<{
        locale: string;
        id: string;
    }>;
}) {
    const { locale, id } = await params;
    if (!isLocale(locale))
        notFound();
    let item;
    try {
        item = await marketItem(id);
    }
    catch {
        notFound();
    }
    return <section className="shop-panel"><span className="blue-eyebrow">#{item.id}</span><h1 className="shop-title">{item.title}</h1><Price locale={locale} price={item.prices}/><p className="shop-muted">{appCopy[locale].botNote}</p><BuyButton item={{ kind: "market", id: item.id, title: item.title, quantity: 1 }}/></section>;
}

src/app/[locale]/product/[id]/page.tsx.content:
import { M_lib_store_products_storeProduct as storeProduct } from "../../../../server.tsx";
import { M_components_BuyButton_BuyButton as BuyButton } from "../../../../ui.tsx";
import { M_lib_pricing_optionalFx as optionalFx, M_lib_pricing_marketMarkup as marketMarkup } from "../../../../server.tsx";
import { M_lib_money_quoteRetail as quoteRetail } from "../../../../shared.tsx";
import { M_components_VerificationPage_VerificationDetail as VerificationDetail } from "../../../../views.tsx";
import { M_components_Price_Price as Price } from "../../../../ui.tsx";
import Link from "next/link";
import { notFound as notFound } from "next/navigation";
import { M_lib_verification_store_verificationItem as verificationItem } from "../../../../server.tsx";
import { M_lib_catalog_catalog as catalog } from "../../../../server.tsx";
import { M_lib_i18n_isLocale as isLocale, M_lib_i18n_copy as copy, M_lib_i18n_locales as locales } from "../../../../shared.tsx";
export const dynamic = "force-dynamic";
export async function generateMetadata({ params, }: {
    params: Promise<{
        locale: string;
        id: string;
    }>;
}) {
    const { locale, id } = await params;
    if (!isLocale(locale))
        notFound();
    const product = id.startsWith("vr_")
        ? await verificationItem(id)
        : await storeProduct(id, locale);
    if (!product)
        notFound();
    const title = typeof product.title === "string" ? product.title : product.title[locale];
    return {
        title,
        alternates: {
            canonical: `/${locale}/product/${id}`,
            languages: Object.fromEntries(locales.map((l) => [l, `/${l}/product/${id}`])),
        },
    };
}
export default async function Page({ params, }: {
    params: Promise<{
        locale: string;
        id: string;
    }>;
}) {
    const { locale, id } = await params;
    if (!isLocale(locale))
        notFound();
    if (!id.startsWith("vr_")) {
        const p = await storeProduct(id, locale);
        if (!p)
            notFound();
        return (<section className="shop-panel mx-auto max-w-3xl">
        <Link href={`/${locale}/${p.category.slug}`} className="text-violet-300">
          ← {copy[locale].back}
        </Link>
        <h1 className="shop-title mt-6">{p.title}</h1>
        {(p.brandAsset?.imageUrl || p.imageUrl) && (<img className="my-7 max-h-64 object-contain" src={p.brandAsset?.imageUrl ?? p.imageUrl!} alt=""/>)}
        <Price price={p.prices} locale={locale}/>
        <p className="shop-muted my-5">
          {p.fulfillmentMode === "MANUAL"
                ? copy[locale].manual
                : locale === "en"
                    ? "Automatic delivery from stock"
                    : "Автоматична видача зі складу"}
        </p>
        <BuyButton item={{ kind: "product", id: p.id, title: p.title, quantity: 1 }} disabled={!p.prices ||
                (p.fulfillmentMode === "INVENTORY" && p._count.inventory === 0)}/>
      </section>);
    }
    const product = await verificationItem(id);
    if (!product)
        notFound();
    const t = copy[locale];
    const fx = await optionalFx();
    const price = fx && !product.unpriced
        ? quoteRetail(product.baseAmount ?? String(product.amountMinor / 100), product.currency, fx, marketMarkup())
        : null;
    if (product.category === "verifications")
        return (<VerificationDetail locale={locale} product={{ ...product, prices: price }}/>);
    return (<section className="mx-auto max-w-3xl rounded-3xl border border-white/10 bg-white/[0.03] p-7 md:p-12">
      <Link href={`/${locale}/${product.category}`} className="text-sm text-violet-300">
        ← {t.back}
      </Link>
      <h1 className="mt-8 text-3xl font-bold">{product.title[locale]}</h1>
      {product.imageUrl && (<img src={product.imageUrl} alt={product.title[locale]} width={640} height={360} className="my-8 max-h-64 w-full object-contain"/>)}
      <p className="mt-5 text-slate-400">
        {t.delivery}: {product.mode === "manual" ? t.manual : t.automatic}
      </p>
      <div className="mt-6">
        {product.unpriced ? t.request : <Price price={price} locale={locale}/>}
      </div>
      <p className="mt-5 text-xs text-amber-200">{t.demo}</p>
      <p className="mt-7 rounded-xl border border-violet-400/20 bg-violet-500/10 p-4 text-sm leading-6 text-violet-200">
        {t.soon}
      </p>
    </section>);
}

src/app/[locale]/telegram-account/[id]/p.content:
import { M_components_BuyButton_BuyButton as BuyButton } from "../../../../ui.tsx";
import { M_components_Flag_Flag as Flag } from "../../../../ui.tsx";
import Link from "next/link";
import { notFound as notFound } from "next/navigation";
import { M_lib_i18n_isLocale as isLocale } from "../../../../shared.tsx";
import { M_lib_telegram_market_getTelegram as getTelegram } from "../../../../server.tsx";
import { M_lib_lzt_http_MarketError as MarketError } from "../../../../server.tsx";
import { M_lib_countries_countryName as countryName } from "../../../../shared.tsx";
import { M_lib_store_copy_shopCopy as shopCopy } from "../../../../shared.tsx";
import { M_components_Price_Price as Price } from "../../../../ui.tsx";
export const dynamic = "force-dynamic";
export default async function Page({ params, }: {
    params: Promise<{
        locale: string;
        id: string;
    }>;
}) {
    const { locale, id } = await params;
    if (!isLocale(locale) || !/^[1-9][0-9]{0,11}$/.test(id))
        notFound();
    const t = shopCopy[locale];
    let item;
    let failed = false;
    try {
        item = await getTelegram(id);
    }
    catch (e) {
        if (e instanceof MarketError && e.code === "not_found")
            notFound();
        failed = true;
    }
    if (failed)
        return (<p role="alert" className="rounded-xl border border-amber-400/20 p-6 text-amber-200">
        {t.unavailable}
      </p>);
    if (!item)
        notFound();
    const yes = (v: boolean | null) => v === null ? t.unknown : v ? t.yes : t.no;
    return (<section className="mx-auto max-w-3xl rounded-3xl border border-white/10 bg-white/[0.04] p-7">
      <Link href={`/${locale}/telegram-accounts/${item.country}`} className="text-sm text-violet-300">
        ← {countryName(item.country, locale)}
      </Link>
      <h1 className="country-heading my-7 flex items-center gap-3 text-3xl font-semibold">
        <Flag country={item.country}/> Telegram ·{" "}
        {countryName(item.country, locale)}
      </h1>
      <p className="mb-5 text-sm text-slate-500">#{item.id}</p>
      <Price price={item.prices} locale={locale}/>
      <dl className="my-7 grid grid-cols-2 gap-4 text-sm">
        {[
            [
                t.spam,
                item.spam === "none"
                    ? t.noSpam
