import { M_lib_i18n_isLocale as isLocale } from "../../../shared.tsx";
import { redirect, notFound } from "next/navigation";
import { M_lib_admin_auth_currentAdmin as currentAdmin, M_lib_admin_products_adminProducts as adminProducts, M_lib_db_db as db } from "../../../server.tsx";
import { M_components_AdminPanel_AdminPanel as AdminPanel, M_components_CommerceAdmin_CommerceAdmin as CommerceAdmin, M_components_AdminLogin_AdminLogin as AdminLogin } from "../../../ui.tsx";
export const dynamic = "force-dynamic";
async function ProductsPage({ searchParams }: {
    searchParams: Promise<{
        locale?: string;
    }>;
}) {
    const admin = await currentAdmin();
    if (!admin)
        redirect("/admin/login");
    const requested = (await searchParams).locale;
    const locale = requested && isLocale(requested) ? requested : admin.locale;
    const [products, logos, audit] = await Promise.all([
        adminProducts(),
        db.brandAsset.findMany({
            orderBy: { name: "asc" },
            select: {
                id: true,
                name: true,
                imageUrl: true,
                color: true,
                group: true,
            },
        }),
        db.adminAuditLog.findMany({
            take: 50,
            orderBy: { createdAt: "desc" },
            select: { id: true, action: true, entityId: true, createdAt: true },
        }),
    ]);
    return (<AdminPanel locale={locale} initialProducts={products} logos={logos} email={admin.email ?? "ADMIN"} audit={audit.map((a) => ({ ...a, createdAt: a.createdAt.toISOString() }))}/>);
}
async function OperationsPage({ searchParams }: {
    searchParams: Promise<{
        locale?: string;
    }>;
}) {
    const admin = await currentAdmin();
    if (!admin)
        redirect("/admin/login");
    const requested = (await searchParams).locale;
    return <CommerceAdmin locale={requested && isLocale(requested) ? requested : admin.locale}/>;
}
async function LoginPage() {
    if (await currentAdmin())
        redirect("/admin");
    return <AdminLogin />;
}

export default async function AdminScreen(props: {params: Promise<{screen?: string[]}>; searchParams: Promise<{locale?: string}>}) {
  const screen = (await props.params).screen ?? [];
  if (!screen.length) return ProductsPage(props);
  if (screen.length !== 1) notFound();
  if (screen[0] === "login") return LoginPage();
  if (screen[0] === "operations") return OperationsPage(props);
  notFound();
}

