const routes: {pattern:string;params:{name:string;many:boolean}[];methods:Record<string,string>}[]=[{"pattern": "^/api/admin/commerce/([^/]+)/?$", "params": [{"name": "action", "many": false}], "methods": {"GET": "M_app_api_admin_commerce__action__route_GET", "POST": "M_app_api_admin_commerce__action__route_POST"}}, {"pattern": "^/api/admin/login/?$", "params": [], "methods": {"POST": "M_app_api_admin_login_route_POST"}}, {"pattern": "^/api/admin/logos/?$", "params": [], "methods": {"GET": "M_app_api_admin_logos_route_GET"}}, {"pattern": "^/api/admin/logout/?$", "params": [], "methods": {"POST": "M_app_api_admin_logout_route_POST"}}, {"pattern": "^/api/admin/products/([^/]+)/?$", "params": [{"name": "id", "many": false}], "methods": {"PATCH": "M_app_api_admin_products__id__route_PATCH"}}, {"pattern": "^/api/admin/products/?$", "params": [], "methods": {"GET": "M_app_api_admin_products_route_GET", "POST": "M_app_api_admin_products_route_POST"}}, {"pattern": "^/api/assets/brands/([^/]+)/?$", "params": [{"name": "id", "many": false}], "methods": {"GET": "M_app_api_assets_brands__id__route_GET"}}, {"pattern": "^/api/auth/([^/]+)/?$", "params": [{"name": "action", "many": false}], "methods": {"GET": "M_app_api_auth__action__route_GET", "POST": "M_app_api_auth__action__route_POST"}}, {"pattern": "^/api/bot/webhook/?$", "params": [], "methods": {"POST": "M_app_api_bot_webhook_route_POST"}}, {"pattern": "^/api/catalog/telegram/?$", "params": [], "methods": {"GET": "M_app_api_catalog_telegram_route_GET"}}, {"pattern": "^/api/crypto/order/?$", "params": [], "methods": {"POST": "M_app_api_crypto_order_route_POST"}}, {"pattern": "^/api/crypto/verify\\-payment/?$", "params": [], "methods": {"GET": "M_app_api_crypto_verify_payment_route_GET", "POST": "M_app_api_crypto_verify_payment_route_POST"}}, {"pattern": "^/api/gifts/([^/]+)/history/?$", "params": [{"name": "address", "many": false}], "methods": {"GET": "M_app_api_gifts__address__history_route_GET"}}, {"pattern": "^/api/gifts/([^/]+)/?$", "params": [{"name": "address", "many": false}], "methods": {"GET": "M_app_api_gifts__address__route_GET"}}, {"pattern": "^/api/gifts/?$", "params": [], "methods": {"GET": "M_app_api_gifts_route_GET"}}, {"pattern": "^/api/health/?$", "params": [], "methods": {"GET": "M_app_api_health_route_GET"}}, {"pattern": "^/api/internal/commerce/([^/]+)/?$", "params": [{"name": "action", "many": false}], "methods": {"POST": "M_app_api_internal_commerce__action__route_POST"}}, {"pattern": "^/api/internal/smm/enqueue/?$", "params": [], "methods": {"POST": "M_app_api_internal_smm_enqueue_route_POST"}}, {"pattern": "^/api/internal/smm/jobs/([^/]+)/?$", "params": [{"name": "id", "many": false}], "methods": {"GET": "M_app_api_internal_smm_jobs__id__route_GET"}}, {"pattern": "^/api/internal/smm/tick/?$", "params": [], "methods": {"POST": "M_app_api_internal_smm_tick_route_POST"}}, {"pattern": "^/api/nft/([^/]+)/?$", "params": [{"name": "action", "many": false}], "methods": {"GET": "M_app_api_nft__action__route_GET", "POST": "M_app_api_nft__action__route_POST"}}, {"pattern": "^/api/payments/webhook/([^/]+)/?$", "params": [{"name": "provider", "many": false}], "methods": {"POST": "M_app_api_payments_webhook__provider__route_POST"}}, {"pattern": "^/api/profile/([^/]+)/?$", "params": [{"name": "action", "many": false}], "methods": {"GET": "M_app_api_profile__action__route_GET", "POST": "M_app_api_profile__action__route_POST"}}, {"pattern": "^/api/shop/([^/]+)/?$", "params": [{"name": "action", "many": false}], "methods": {"GET": "M_app_api_shop__action__route_GET", "POST": "M_app_api_shop__action__route_POST"}}, {"pattern": "^/api/shop/delivery/([^/]+)/?$", "params": [{"name": "id", "many": false}], "methods": {"GET": "M_app_api_shop_delivery__id__route_GET"}}, {"pattern": "^/api/shop/handoff/([^/]+)/?$", "params": [{"name": "action", "many": false}], "methods": {"POST": "M_app_api_shop_handoff__action__route_POST"}}, {"pattern": "^/api/shop/orders/([^/]+)/?$", "params": [{"name": "id", "many": false}], "methods": {"GET": "M_app_api_shop_orders__id__route_GET"}}, {"pattern": "^/api/smm/quote/?$", "params": [], "methods": {"POST": "M_app_api_smm_quote_route_POST"}}, {"pattern": "^/api/smm/services/?$", "params": [], "methods": {"GET": "M_app_api_smm_services_route_GET"}}, {"pattern": "^/api/static/(.+)/?$", "params": [{"name": "path", "many": true}], "methods": {"GET": "M_app_api_static_____path__route_GET"}}, {"pattern": "^/api/tonconnect\\-manifest/?$", "params": [], "methods": {"GET": "M_app_api_tonconnect_manifest_route_GET"}}, {"pattern": "^/api/wallet/balance/?$", "params": [], "methods": {"GET": "M_app_api_wallet_balance_route_GET"}}, {"pattern": "^/api/webhooks/tonkeeper/?$", "params": [], "methods": {"POST": "M_app_api_webhooks_tonkeeper_route_POST", "GET": "M_app_api_webhooks_tonkeeper_route_GET"}}];
async function dispatch(request:Request,context:{params:Promise<{path:string[]}>}){
 // After a Next rewrite request.url can retain the public asset URL. Match the resolved route.
 const path='/api/'+(await context.params).path.map(encodeURIComponent).join('/');
 for(const route of routes){const match=new RegExp(route.pattern).exec(path);if(!match)continue;
 const name=route.methods[request.method];
 if(!name)return new Response(null,{status:405,headers:{Allow:Object.keys(route.methods).join(', ')}});
 const params:Record<string,string|string[]>={};try{route.params.forEach((p,i)=>{params[p.name]=p.many?match[i+1].split('/').map(decodeURIComponent):decodeURIComponent(match[i+1]);});}catch{return new Response(null,{status:400});}
 return (handlers[name as keyof typeof handlers] as unknown as Handler)(request,{params:Promise.resolve(params)});
 }
 return Response.json({error:'not_found'},{status:404});
}
