import { M_lib_admin_auth_adminFromToken as adminFromToken, M_lib_admin_auth_adminCookie as adminCookie } from "./server.tsx";
import { randomBytes as randomBytes } from "node:crypto";
import { NextRequest as NextRequest, NextResponse as NextResponse } from "next/server";
import { M_lib_security_policy_contentPolicy as contentPolicy, M_lib_security_policy_privatePath as privatePath, M_lib_security_policy_securityHeaders as securityHeaders } from "./server.tsx";
export async function proxy(request: NextRequest) {
    const path = request.nextUrl.pathname;
    const headers = securityHeaders();
    if (privatePath(path))
        return new NextResponse("Not found", {
            status: 404,
            headers: { ...headers, "Cache-Control": "no-store" },
        });
    const adminPath = path === "/admin" ||
        path.startsWith("/admin/") ||
        path.startsWith("/api/admin/");
    // The login form is public; its POST still verifies signed Telegram data and ADMIN_ID.
    if (adminPath && path !== "/api/admin/login" && path !== "/admin/login") {
        let authorized = false;
        try {
            authorized = Boolean(await adminFromToken(request.cookies.get(adminCookie)?.value));
        }
        catch { }
        if (!authorized && path.startsWith("/api/admin/"))
            return NextResponse.json({ error: "forbidden" }, { status: 403, headers: { ...headers, "Cache-Control": "no-store" } });
        if (!authorized)
            return new NextResponse("<!doctype html><html><head><meta name=viewport content=width=device-width></head><body style='margin:0;display:grid;place-items:center;min-height:100svh;background:#0B0E14;color:#fff;font-family:Arial'><main><h1>403</h1><p>Forbidden</p></main></body></html>", {
                status: 403,
                headers: {
                    ...headers,
                    "Content-Type": "text/html; charset=utf-8",
                    "Cache-Control": "no-store",
                },
            });
    }
    const production = process.env.NODE_ENV === "production";
    const nonce = randomBytes(18).toString("base64");
    const policy = contentPolicy(nonce, path === "/admin" || path.startsWith("/admin/"), production, adminPath);
    const forwarded = new Headers(request.headers);
    // Do not trust a caller-supplied nonce or CSP. Next uses this policy to nonce its SSR scripts.
    forwarded.set("x-nonce", nonce);
    forwarded.set("Content-Security-Policy", policy);
    const response = NextResponse.next({ request: { headers: forwarded } });
    for (const [key, value] of Object.entries(headers))
        response.headers.set(key, value);
    if (!path.startsWith("/api/") &&
        !path.startsWith("/_next/") &&
        !path.startsWith("/assets/")) {
        response.headers.set("Content-Security-Policy", policy);
        response.headers.set("Cache-Control", "private, no-store");
    }
    if (production && request.nextUrl.protocol === "https:")
        response.headers.set("Strict-Transport-Security", "max-age=15552000");
    return response;
}
export const config = { matcher: "/:path*" };

