    function harness(migrationCode = 0) {
      const runs = [],
        completed = [],
        signals = new EventEmitter();
      const spawnChild = (_bin, args, { env }) => {
        const child = new EventEmitter();
        child.args = args;
        child.env = env;
        child.kills = [];
        child.kill = (signal) => {
          child.kills.push(signal);
          queueMicrotask(() => child.emit("exit", 0));
