      });
      assert.equal(parseBotOrderPayload("buy_admin-" + token), null);
      assert.throws(() => botOrderPayload("../admin", token));
      assert.throws(() => botOrderPayload("cart", "A".repeat(43)));
      assert.equal(handoffCategory([{ kind: "gift" }]), "nft-gifts");
      assert.equal(
